      const searchPerPage = _sCols * 2;
      const searchTotal = Math.ceil((this._searchResults || []).length / searchPerPage);
      const sp = this._searchPage || 0;
      const hasPrevS = sp > 0;
      const hasNextS = sp < searchTotal - 1;
