        prevAttr: 'data-section="right" data-dir="prev"',
        nextAttr: 'data-section="right" data-dir="next"',
        lastAttr: 'data-section="right" data-dir="last"',
        dotAttr: "data-page",
        dotSecAttr: 'data-section="right" '
